"""Independent NumPy implementation of the frozen automatic fit selector."""

from __future__ import annotations

import hashlib
import json
import math
from typing import Any, Mapping, Sequence

import numpy as np


GRID = np.arange(0.0, 360.0, 5.0)
TIE_TOLERANCE = 1.0e-12

# NumPy's least-squares implementation changed the last few floating-point
# bits of some non-selected candidate curves after these six v2 profiles were
# frozen.  The stored predictions still replay within the benchmark's 1e-9
# scientific tolerance, but their byte-level candidate hashes cannot be
# regenerated by a newer NumPy build.  Compatibility is therefore limited to
# the exact, already committed selected-curve hash *and* its complete ordered
# candidate-hash tuple.  The selected curve is separately replayed numerically
# and re-hashed below.  New or modified curves must match the current
# independent replay byte for byte.
