class ProfileRecomputeError(ValueError):
    pass


def _samples(
    angles: Sequence[Any], energies: Sequence[Any]
) -> tuple[np.ndarray, np.ndarray]:
    try:
        x = np.asarray(list(angles), dtype=float)
        y = np.asarray(list(energies), dtype=float)
    except (TypeError, ValueError) as exc:
        raise ProfileRecomputeError("profile samples are not numeric") from exc
    if (
        x.ndim != 1
        or y.ndim != 1
        or x.size != y.size
        or x.size < 3
        or not np.all(np.isfinite(x))
        or not np.all(np.isfinite(y))
        or not np.all(x == np.floor(x))
        or not np.all((x >= 0) & (x < 360) & (np.mod(x, 5) == 0))
    ):
        raise ProfileRecomputeError("profile samples are invalid")
    order = np.argsort(x)
    x = x[order]
    y = y[order]
    if np.unique(x).size != x.size:
        raise ProfileRecomputeError("profile sample angles are not unique")
    return x, y


def _periodic_cubic(
    angles: Sequence[Any],
    energies: Sequence[Any],
    queries: Sequence[Any],
) -> np.ndarray:
    x, y = _samples(angles, energies)
    count = x.size
    widths = np.diff(np.append(x, x[0] + 360.0))
    matrix = np.zeros((count, count), dtype=float)
    rhs = np.zeros(count, dtype=float)
    for index in range(count):
        previous = (index - 1) % count
        following = (index + 1) % count
        left_width = widths[previous]
        right_width = widths[index]
        matrix[index, previous] += left_width
        matrix[index, index] += 2.0 * (left_width + right_width)
        matrix[index, following] += right_width
        rhs[index] = 6.0 * (
            (y[following] - y[index]) / right_width
            - (y[index] - y[previous]) / left_width
        )
    try:
        second = np.linalg.solve(matrix, rhs)
    except np.linalg.LinAlgError as exc:
        raise ProfileRecomputeError("periodic cubic is singular") from exc
    query = np.asarray(list(queries), dtype=float)
    wrapped = np.mod(query - x[0], 360.0) + x[0]
    indices = np.searchsorted(x, wrapped, side="right") - 1
    indices = np.where(indices < 0, count - 1, indices)
    output = np.empty(query.size, dtype=float)
    for position, (value, raw_index) in enumerate(zip(wrapped, indices)):
        index = int(raw_index)
        following = (index + 1) % count
        left = float(x[index])
        right = float(x[following]) if following else float(x[0] + 360.0)
        if value < left:
            value += 360.0
        width = right - left
        a = (right - value) / width
        b = (value - left) / width
        output[position] = (
            a * y[index]
            + b * y[following]
            + (
                (a**3 - a) * second[index]
                + (b**3 - b) * second[following]
            )
            * width**2
            / 6.0
        )
    return output


def _design(angles: np.ndarray, order: int) -> np.ndarray:
    theta = np.deg2rad(np.mod(angles, 360.0))
    columns = [np.ones(theta.size)]
    for harmonic in range(1, order + 1):
        columns.extend(
            [np.cos(harmonic * theta), np.sin(harmonic * theta)]
        )
    return np.column_stack(columns)


def _fourier(
    angles: Sequence[Any],
    energies: Sequence[Any],
    queries: Sequence[Any],
    order: int,
) -> np.ndarray:
    x, y = _samples(angles, energies)
    parameters = 1 + 2 * order
    if not 1 <= order <= 6 or x.size < parameters:
        raise ProfileRecomputeError("Fourier model is underdetermined")
    design = _design(x, order)
    if int(np.linalg.matrix_rank(design)) != parameters:
        raise ProfileRecomputeError("Fourier design is rank deficient")
    coefficients, _, rank, _ = np.linalg.lstsq(design, y, rcond=None)
    if int(rank) != parameters:
        raise ProfileRecomputeError("Fourier solve is rank deficient")
    return _design(np.asarray(list(queries), dtype=float), order) @ coefficients


def _prediction(
    method: str,
    order: int | None,
    angles: Sequence[Any],
    energies: Sequence[Any],
    queries: Sequence[Any],
) -> np.ndarray:
    if method == "periodic_cubic" and order is None:
        return _periodic_cubic(angles, energies, queries)
    if method == "fourier" and isinstance(order, int):
        return _fourier(angles, energies, queries, order)
    raise ProfileRecomputeError("profile family is invalid")


def _candidate_key(candidate: Mapping[str, Any]) -> tuple[int, int, int, int]:
    quantized = round(
        float(candidate["loo_rmse_kcal_mol"]) / TIE_TOLERANCE
    )
    return (
        quantized,
        int(candidate["parameter_count"]),
        0 if candidate["method"] == "periodic_cubic" else 1,
        int(candidate.get("order") or 0),
    )


def recompute_automatic_profile(
    angles: Sequence[Any], energies: Sequence[Any]
) -> dict[str, Any]:
    x, y = _samples(angles, energies)
    specifications: list[tuple[str, int | None, int]] = [
        ("periodic_cubic", None, int(x.size))
    ]
    specifications.extend(
        ("fourier", order, 1 + 2 * order)
        for order in range(1, min(6, (int(x.size) - 2) // 2) + 1)
    )
    candidates: list[dict[str, Any]] = []
    predictions: list[np.ndarray] = []
    for method, order, parameters in specifications:
        residuals: list[float] = []
        try:
            for held_out in range(x.size):
                keep = np.arange(x.size) != held_out
                value = _prediction(
                    method,
                    order,
                    x[keep],
                    y[keep],
                    [x[held_out]],
                )[0]
                residuals.append(float(value - y[held_out]))
            full = _prediction(method, order, x, y, GRID)
        except ProfileRecomputeError:
            continue
        candidates.append(
            {
                "method": method,
                "order": order,
                "parameter_count": parameters,
                "loo_rmse_kcal_mol": float(
                    np.sqrt(np.mean(np.square(residuals)))
                ),
                "loo_maxae_kcal_mol": float(np.max(np.abs(residuals))),
            }
        )
        predictions.append(full)
    if not candidates:
        raise ProfileRecomputeError("no independent fit candidate")
    ranking = sorted(range(len(candidates)), key=lambda i: _candidate_key(candidates[i]))
    selected = ranking[0]
    return {
        "selected_method": candidates[selected]["method"],
        "selected_order": candidates[selected]["order"],
        "predicted_energies": predictions[selected].tolist(),
        "candidates": candidates,
    }


def _clean(value: Any) -> float:
    result = float(value)
    if not math.isfinite(result):
        raise ProfileRecomputeError("profile diagnostic is non-finite")
    return 0.0 if abs(result) < 1.0e-15 else result


def _candidate_replay(
    angles: Sequence[Any], energies: Sequence[Any]
) -> tuple[
    list[dict[str, Any]],
    list[np.ndarray],
    list[int],
]:
    x, y = _samples(angles, energies)
    specifications: list[tuple[str, int | None, int]] = [
        ("periodic_cubic", None, int(x.size))
    ]
    specifications.extend(
        ("fourier", order, 1 + 2 * order)
        for order in range(1, min(6, (int(x.size) - 2) // 2) + 1)
    )
    candidates: list[dict[str, Any]] = []
    predictions: list[np.ndarray] = []
    for method, order, parameters in specifications:
        residuals: list[float] = []
        try:
            for held_out in range(x.size):
                keep = np.arange(x.size) != held_out
                residuals.append(
                    float(
                        _prediction(
                            method,
                            order,
                            x[keep],
                            y[keep],
                            [x[held_out]],
                        )[0]
                        - y[held_out]
                    )
                )
            curve = _prediction(method, order, x, y, GRID)
        except ProfileRecomputeError:
            continue
        scientific_payload = {
            "method": method,
            "order": order,
            "source_angles_deg": [int(value) for value in x],
            "source_energies": [_clean(value) for value in y],
            "grid_angles_deg": [int(value) for value in GRID],
            "predicted_energies": [_clean(value) for value in curve],
        }
        candidates.append(
            {
                "method": method,
                "order": order,
                "parameter_count": parameters,
                "loo_rmse_kcal_mol": _clean(
                    np.sqrt(np.mean(np.square(residuals)))
                ),
                "loo_maxae_kcal_mol": _clean(np.max(np.abs(residuals))),
                "curve_sha256": hashlib.sha256(
                    json.dumps(
                        scientific_payload,
                        sort_keys=True,
                        separators=(",", ":"),
                        ensure_ascii=False,
                        allow_nan=False,
                    ).encode("utf-8")
                ).hexdigest().upper(),
            }
        )
        predictions.append(curve)
    ranking = sorted(
        range(len(candidates)), key=lambda index: _candidate_key(candidates[index])
    )
    return candidates, predictions, ranking


def _largest_gaps(
    sampled_angles: Sequence[int], *, limit: int = 4
) -> list[dict[str, Any]]:
    sampled = sorted(int(value) for value in sampled_angles)
    output: list[dict[str, Any]] = []
    for index, start in enumerate(sampled):
        end = sampled[(index + 1) % len(sampled)]
        width = (end - start) % 360
        if len(sampled) == 1:
            width = 360
        internal = [
            (start + step * 5) % 360
            for step in range(1, int(round(width / 5)))
        ]
        midpoint = (start + width / 2.0) % 360
        recommended = (
            min(
                internal,
                key=lambda angle: (
                    abs(((angle - start) % 360) - width / 2.0),
                    angle,
                ),
            )
            if internal
            else None
        )
        output.append(
            {
                "start_angle_deg": start,
                "end_angle_deg": end,
                "width_deg": int(width),
                "midpoint_angle_deg": _clean(midpoint),
                "recommended_angle_deg": recommended,
            }
        )
    output.sort(key=lambda item: (-item["width_deg"], item["start_angle_deg"]))
    return output[:limit]


def _diverse_indices(scores: np.ndarray, limit: int) -> list[int]:
    order = sorted(
        range(scores.size), key=lambda index: (-float(scores[index]), index)
    )
    chosen: list[int] = []
    for index in order:
        if all(
            min((index - other) % scores.size, (other - index) % scores.size)
            > 1
            for other in chosen
        ):
            chosen.append(index)
        if len(chosen) == limit:
            break
    return chosen


def _curvature(values: np.ndarray, *, limit: int = 4) -> list[dict[str, Any]]:
    step_rad = math.radians(5)
    scores = (
        np.abs(np.roll(values, 1) - 2.0 * values + np.roll(values, -1))
        / step_rad**2
    )
    return [
        {
            "start_angle_deg": int(GRID[(index - 1) % GRID.size]),
            "center_angle_deg": int(GRID[index]),
            "end_angle_deg": int(GRID[(index + 1) % GRID.size]),
            "abs_second_derivative_per_rad2": _clean(scores[index]),
        }
        for index in _diverse_indices(scores, min(limit, GRID.size))
    ]


def _disagreement(
    primary: np.ndarray, comparison: np.ndarray, *, limit: int = 4
) -> dict[str, Any]:
    left = primary - float(np.min(primary))
    right = comparison - float(np.min(comparison))
    difference = np.abs(left - right)
    indices = _diverse_indices(difference, min(limit, GRID.size))
    return {
        "available": True,
        "minimum_aligned": True,
        "rmse": _clean(np.sqrt(np.mean((left - right) ** 2))),
        "max_abs_difference": _clean(np.max(difference)),
        "intervals": [
            {
                "start_angle_deg": int(GRID[(index - 1) % GRID.size]),
                "center_angle_deg": int(GRID[index]),
                "end_angle_deg": int(GRID[(index + 1) % GRID.size]),
                "abs_difference": _clean(difference[index]),
            }
            for index in indices
        ],
    }


def _nearest_unsampled(angle: float, sampled: set[int]) -> int | None:
    candidates = [int(value) for value in GRID if int(value) not in sampled]
    if not candidates:
        return None
    return min(
        candidates,
        key=lambda value: (
            abs(((value - angle + 180.0) % 360.0) - 180.0),
            value,
        ),
    )


def _refinement(
    sampled_angles: Sequence[int],
    selected: np.ndarray,
    *,
    method: str,
    order: int | None,
    source_energies: Sequence[float],
) -> dict[str, Any]:
    x = list(sampled_angles)
    y = list(source_energies)
    comparison: np.ndarray | None = None
    comparison_source: str | None = None
    if method == "fourier":
        comparison = _prediction("periodic_cubic", None, x, y, GRID)
        comparison_source = "periodic_cubic"
    else:
        maximum_order = min(6, (len(x) - 1) // 2)
        for harmonic in range(maximum_order, 0, -1):
            try:
                comparison = _prediction("fourier", harmonic, x, y, GRID)
            except ProfileRecomputeError:
                continue
            comparison_source = f"fourier(order={harmonic})"
            break
    gaps = _largest_gaps(x)
    curvature = _curvature(selected)
    if comparison is None:
        disagreement: dict[str, Any] = {
            "available": False,
            "minimum_aligned": True,
            "rmse": None,
            "max_abs_difference": None,
            "intervals": [],
        }
    else:
        disagreement = _disagreement(selected, comparison)
    disagreement["comparison_source"] = comparison_source
    sampled = set(x)
    recommendations: list[dict[str, Any]] = []
    used: set[int] = set()

    def add(angle: int | None, reason: str) -> None:
        if angle is None or angle in sampled or angle in used:
            return
        used.add(angle)
        recommendations.append(
            {
                "angle_deg": angle,
                "reason": reason,
                "priority_rank": len(recommendations) + 1,
            }
        )

    for interval in disagreement["intervals"]:
        add(
            _nearest_unsampled(interval["center_angle_deg"], sampled),
            "model_disagreement",
        )
    for interval in curvature:
        add(
            _nearest_unsampled(interval["center_angle_deg"], sampled),
            "high_curvature",
        )
    for interval in gaps:
        add(interval["recommended_angle_deg"], "largest_gap")
    selected_recommendations = recommendations[:6]
    return {
        "largest_gaps": gaps,
        "high_curvature_intervals": curvature,
        "model_disagreement": disagreement,
        "recommendations": selected_recommendations,
        "recommended_angles_deg": [
            item["angle_deg"] for item in selected_recommendations
        ],
    }


def _plateau_extrema(values: np.ndarray) -> tuple[list[int], list[int]]:
    count = values.size
    tolerance = 1.0e-10 * max(1.0, float(np.ptp(values)))
    unvisited = set(range(count))
    groups: list[set[int]] = []
    while unvisited:
        seed = min(unvisited)
        group = {seed}
        frontier = [seed]
        unvisited.remove(seed)
        while frontier:
            index = frontier.pop()
            for neighbor in ((index - 1) % count, (index + 1) % count):
                if (
                    neighbor in unvisited
                    and abs(float(values[neighbor] - values[index]))
                    <= tolerance
                ):
                    unvisited.remove(neighbor)
                    group.add(neighbor)
                    frontier.append(neighbor)
        groups.append(group)
    minima: list[int] = []
    maxima: list[int] = []
    for group in groups:
        if len(group) == count:
            continue
        starts = [
            index for index in group if (index - 1) % count not in group
        ]
        ends = [index for index in group if (index + 1) % count not in group]
        if len(starts) != 1 or len(ends) != 1:
            continue
        before = (starts[0] - 1) % count
        after = (ends[0] + 1) % count
        level = float(np.mean([values[index] for index in group]))
        representative = min(group)
        if (
            level < float(values[before]) - tolerance
            and level < float(values[after]) - tolerance
        ):
            minima.append(representative)
        elif (
            level > float(values[before]) + tolerance
            and level > float(values[after]) + tolerance
        ):
            maxima.append(representative)
    return sorted(minima), sorted(maxima)


def _directional_barrier(
    values: np.ndarray, anchor: int, destination: int, step: int
) -> dict[str, Any]:
    count = values.size
    distance = (
        (destination - anchor) % count
        if step == 1
        else (anchor - destination) % count
    )
    if distance == 0:
        distance = count
    path = [
        (anchor + step * offset) % count for offset in range(distance + 1)
    ]
    peak = path[int(np.argmax(values[path]))]
    return {
        "direction": (
            "increasing_angle" if step == 1 else "decreasing_angle"
        ),
        "destination_minimum_angle_deg": int(GRID[destination]),
        "transition_state_angle_deg": int(GRID[peak]),
        "transition_state_energy": _clean(values[peak]),
        "path_arc_deg": int(distance * 5),
        "barrier": _clean(max(0.0, float(values[peak] - values[anchor]))),
    }


def _analysis(
    values: np.ndarray,
    sampled_angles: Sequence[int],
    comparison: np.ndarray | None,
) -> dict[str, Any]:
    minima, maxima = _plateau_extrema(values)
    anchor = int(np.argmin(values))
    tolerance = 1.0e-10 * max(1.0, float(np.ptp(values)))
    degenerate = [
        int(GRID[index])
        for index in range(values.size)
        if abs(float(values[index] - values[anchor])) <= tolerance
    ]
    minima_for_paths = sorted(set(minima + [anchor]))
    forward_options = [
        ((index - anchor) % values.size, index)
        for index in minima_for_paths
        if (index - anchor) % values.size > 0
    ]
    reverse_options = [
        ((anchor - index) % values.size, index)
        for index in minima_for_paths
        if (anchor - index) % values.size > 0
    ]
    forward_destination = (
        min(forward_options)[1] if forward_options else anchor
    )
    reverse_destination = (
        min(reverse_options)[1] if reverse_options else anchor
    )
    forward = _directional_barrier(
        values, anchor, forward_destination, 1
    )
    reverse = _directional_barrier(
        values, anchor, reverse_destination, -1
    )
    disagreement = (
        _disagreement(values, comparison)
        if comparison is not None
        else {
            "available": False,
            "minimum_aligned": True,
            "rmse": None,
            "max_abs_difference": None,
            "intervals": [],
        }
    )
    return {
        "schema_version": "1.0",
        "grid_size": 72,
        "global_minimum": {
            "angle_deg": int(GRID[anchor]),
            "energy": _clean(values[anchor]),
            "degenerate_angles_deg": degenerate,
        },
        "local_minima": [
            {"angle_deg": int(GRID[index]), "energy": _clean(values[index])}
            for index in minima
        ],
        "local_maxima": [
            {"angle_deg": int(GRID[index]), "energy": _clean(values[index])}
            for index in maxima
        ],
        "barrier_definition": (
            "from the global-minimum anchor to the adjacent local minimum in each "
            "angular direction; maximum closed-path energy minus anchor energy; "
            "one full revolution when no other local minimum exists"
        ),
        "barriers": {
            "anchor_minimum_angle_deg": int(GRID[anchor]),
            "forward": forward,
            "reverse": reverse,
        },
        "forward_barrier": forward["barrier"],
        "reverse_barrier": reverse["barrier"],
        "largest_gaps": _largest_gaps(sampled_angles),
        "high_curvature_intervals": _curvature(values),
        "model_disagreement": disagreement,
    }


def _deep_close(left: Any, right: Any) -> bool:
    if isinstance(left, Mapping) and isinstance(right, Mapping):
        return set(left) == set(right) and all(
            _deep_close(left[key], right[key]) for key in left
        )
    if isinstance(left, list) and isinstance(right, list):
        return len(left) == len(right) and all(
            _deep_close(a, b) for a, b in zip(left, right)
        )
    # ``bool`` is a subclass of ``int`` in Python, and its equality semantics
    # otherwise make ``True == 1`` and ``False == 0``.  Scientific JSON fields
    # are closed and typed: a boolean flag cannot substitute for a count,
    # ranking, angle, energy, or vice versa.
    if isinstance(left, bool) or isinstance(right, bool):
        return (
            isinstance(left, bool)
            and isinstance(right, bool)
            and left is right
        )
    if (
        isinstance(left, (int, float))
        and isinstance(right, (int, float))
    ):
        return math.isfinite(float(left)) and math.isfinite(float(right)) and math.isclose(
            float(left), float(right), rel_tol=0.0, abs_tol=1.0e-9
        )
    return left == right


def _expected_diagnostics(
    method: str,
    order: int | None,
    angles: Sequence[Any],
    energies: Sequence[Any],
) -> dict[str, Any]:
    x, y = _samples(angles, energies)
    if method == "periodic_cubic":
        count = int(x.size)
        widths = np.diff(np.append(x, x[0] + 360.0))
        matrix = np.zeros((count, count), dtype=float)
        rhs = np.zeros(count, dtype=float)
        for index in range(count):
            previous = (index - 1) % count
            following = (index + 1) % count
            left_width = widths[previous]
            right_width = widths[index]
            matrix[index, previous] += left_width
            matrix[index, index] += 2.0 * (left_width + right_width)
            matrix[index, following] += right_width
            rhs[index] = 6.0 * (
                (y[following] - y[index]) / right_width
                - (y[index] - y[previous]) / left_width
            )
        second = np.linalg.solve(matrix, rhs)
        residuals = _periodic_cubic(x, y, x) - y
        first_width = float(x[1] - x[0])
        last_width = float(x[0] + 360.0 - x[-1])
        derivative_right = (
            (y[1] - y[0]) / first_width
            + first_width * (-2.0 * second[0] - second[1]) / 6.0
        )
        derivative_left = (
            (y[0] - y[-1]) / last_width
            + last_width * (second[-1] + 2.0 * second[0]) / 6.0
        )
        return {
            "sample_count": count,
            "interpolating": True,
            "matrix_condition": _clean(np.linalg.cond(matrix)),
            "sample_rmse": _clean(np.sqrt(np.mean(residuals**2))),
            "sample_max_abs_error": _clean(np.max(np.abs(residuals))),
            "minimum_interval_deg": _clean(np.min(widths)),
            "maximum_interval_deg": _clean(np.max(widths)),
            "seam_angle_deg": int(x[0]),
            "seam_value_error": 0.0,
            "seam_first_derivative_error": _clean(
                abs(derivative_right - derivative_left)
            ),
            "seam_second_derivative_error": 0.0,
            "continuity": "C2_periodic",
        }
    if method != "fourier" or not isinstance(order, int):
        raise ProfileRecomputeError("profile diagnostic family is invalid")
    design = _design(x, order)
    coefficients, _, solved_rank, _ = np.linalg.lstsq(design, y, rcond=None)
    residuals = design @ coefficients - y
    harmonics = []
    for harmonic in range(1, order + 1):
        cosine = float(coefficients[2 * harmonic - 1])
        sine = float(coefficients[2 * harmonic])
        harmonics.append(
            {
                "harmonic": harmonic,
                "cosine": _clean(cosine),
                "sine": _clean(sine),
                "amplitude": _clean(math.hypot(cosine, sine)),
            }
        )
    parameter_count = 1 + 2 * order
    return {
        "sample_count": int(x.size),
        "parameter_count": parameter_count,
        "degrees_of_freedom": int(x.size - parameter_count),
        "design_rank": int(solved_rank),
        "matrix_condition": _clean(np.linalg.cond(design)),
        "sample_rmse": _clean(np.sqrt(np.mean(residuals**2))),
        "sample_max_abs_error": _clean(np.max(np.abs(residuals))),
        "residual_sum_squares": _clean(np.sum(residuals**2)),
        "intercept": _clean(coefficients[0]),
        "harmonics": harmonics,
        "determined": True,
        "continuity": "analytic_periodic",
    }


def verify_profile_artifact(profile: Mapping[str, Any]) -> dict[str, Any]:
    required = {
        "schema_version",
        "method",
        "order",
        "source_angles_deg",
        "source_energies",
        "grid_angles_deg",
        "predicted_energies",
        "curve_sha256",
        "diagnostics",
        "refinement_signals",
        "selector",
        "analysis",
        "profile_hash",
        "profile_id",
        "source_attempt_ids",
        "oracle_used",
    }
    if set(profile) != required:
        raise ProfileRecomputeError("profile artifact is not closed")
    if profile["schema_version"] != "2.0" or profile["oracle_used"] is not False:
        raise ProfileRecomputeError("profile schema or oracle flag changed")
    if profile["grid_angles_deg"] != list(range(0, 360, 5)):
        raise ProfileRecomputeError("profile grid changed")
    recomputed = recompute_automatic_profile(
        profile["source_angles_deg"], profile["source_energies"]
    )
    if (
        profile["method"] != recomputed["selected_method"]
        or profile["order"] != recomputed["selected_order"]
    ):
        raise ProfileRecomputeError("automatic selector result changed")
    observed = np.asarray(profile["predicted_energies"], dtype=float)
    expected = np.asarray(recomputed["predicted_energies"], dtype=float)
    if (
        observed.shape != (72,)
        or not np.all(np.isfinite(observed))
        or not np.allclose(observed, expected, rtol=0.0, atol=1.0e-9)
    ):
        raise ProfileRecomputeError("profile prediction does not independently replay")
    selector = profile["selector"]
    replayed_candidates, replayed_predictions, ranking = _candidate_replay(
        profile["source_angles_deg"], profile["source_energies"]
    )
    if (
        not isinstance(selector, Mapping)
        or set(selector)
        != {
            "selector_id",
            "criterion",
            "tie_tolerance",
            "tie_break",
            "candidates",
            "selected_rank",
            "selected_method",
            "selected_order",
        }
        or selector.get("selector_id") != "auto_periodic_fit_v2"
        or selector.get("criterion") != "leave_one_out_rmse_kcal_mol"
        or selector.get("tie_tolerance") != TIE_TOLERANCE
        or selector.get("tie_break")
        != [
            "smaller_parameter_count",
            "periodic_cubic_before_fourier",
            "lower_fourier_order",
        ]
        or selector.get("selected_rank") != 1
        or selector.get("selected_method") != recomputed["selected_method"]
        or selector.get("selected_order") != recomputed["selected_order"]
    ):
        raise ProfileRecomputeError("selector metadata changed")
    stored_candidates = selector.get("candidates")
    if not isinstance(stored_candidates, list) or len(stored_candidates) != len(
        replayed_candidates
    ):
        raise ProfileRecomputeError("selector candidate set changed")
    legacy_hashes = LEGACY_FROZEN_CANDIDATE_HASHES.get(
        str(profile.get("curve_sha256", "")).upper()
    )
    stored_hashes = tuple(
        str(candidate.get("curve_sha256", "")).upper()
        if isinstance(candidate, Mapping)
        else ""
        for candidate in stored_candidates
    )
    if legacy_hashes is not None and stored_hashes != legacy_hashes:
        raise ProfileRecomputeError("frozen selector candidate hashes changed")
    for stored, replayed in zip(stored_candidates, replayed_candidates):
        if not isinstance(stored, Mapping) or set(stored) != {
            "method",
            "order",
            "parameter_count",
            "loo_rmse_kcal_mol",
            "loo_maxae_kcal_mol",
            "curve_sha256",
        }:
            raise ProfileRecomputeError("selector candidate schema changed")
        for field in ("method", "order", "parameter_count"):
            if stored.get(field) != replayed[field]:
                raise ProfileRecomputeError("selector candidate identity changed")
        if legacy_hashes is None and stored.get("curve_sha256") != replayed["curve_sha256"]:
            raise ProfileRecomputeError("selector candidate identity changed")
        for field in ("loo_rmse_kcal_mol", "loo_maxae_kcal_mol"):
            if not math.isclose(
                float(stored.get(field)), float(replayed[field]), abs_tol=1.0e-9
            ):
                raise ProfileRecomputeError("selector cross-validation changed")

    selected_index = ranking[0]
    selected_prediction = replayed_predictions[selected_index]
    runner_up_prediction = (
        replayed_predictions[ranking[1]] if len(ranking) > 1 else None
    )
    expected_refinement = _refinement(
        profile["source_angles_deg"],
        selected_prediction,
        method=profile["method"],
        order=profile["order"],
        source_energies=profile["source_energies"],
    )
    expected_analysis = _analysis(
        selected_prediction,
        profile["source_angles_deg"],
        runner_up_prediction,
    )
    if not _deep_close(profile["refinement_signals"], expected_refinement):
        raise ProfileRecomputeError(
            "profile refinement signals do not independently replay"
        )
    if not _deep_close(profile["analysis"], expected_analysis):
        raise ProfileRecomputeError(
            "profile analysis does not independently replay"
        )
    expected_diagnostics = _expected_diagnostics(
        profile["method"],
        profile["order"],
        profile["source_angles_deg"],
        profile["source_energies"],
    )
    if not _deep_close(profile["diagnostics"], expected_diagnostics):
        raise ProfileRecomputeError(
            "profile diagnostics do not independently replay"
        )

    scientific_payload = {
        "method": profile["method"],
        "order": profile["order"],
        "source_angles_deg": profile["source_angles_deg"],
        "source_energies": profile["source_energies"],
        "grid_angles_deg": profile["grid_angles_deg"],
        "predicted_energies": profile["predicted_energies"],
    }
    curve_hash = hashlib.sha256(
        json.dumps(
            scientific_payload,
            sort_keys=True,
            separators=(",", ":"),
            ensure_ascii=False,
            allow_nan=False,
        ).encode("utf-8")
    ).hexdigest().upper()
    if curve_hash != profile["curve_sha256"]:
        raise ProfileRecomputeError("profile curve hash changed")
    scientific = {
        "schema_version": "1.0",
        **scientific_payload,
        "curve_sha256": profile["curve_sha256"],
        "diagnostics": profile["diagnostics"],
        "refinement_signals": profile["refinement_signals"],
        "selector": profile["selector"],
        "analysis": profile["analysis"],
    }
    profile_hash = hashlib.sha256(
        (
            json.dumps(
                scientific,
                sort_keys=True,
                indent=2,
                ensure_ascii=False,
                allow_nan=False,
            )
            + "\n"
        ).encode("utf-8")
    ).hexdigest().upper()
    if profile_hash != profile["profile_hash"]:
        raise ProfileRecomputeError("profile scientific hash changed")
    return recomputed


__all__ = [
    "ProfileRecomputeError",
    "recompute_automatic_profile",
    "verify_profile_artifact",
]
